const byName = new Map(PUBLIC_ICONS.flatMap(item => [[item.id.toLowerCase(), item] as const, [item.name.toLowerCase(), item] as const]));
export const findPublicIcon = (value?: string) => value ? byName.get(value.trim().toLowerCase()) : undefined;
